fn solve(a: i8, b: i8, s: Vec<char>) -> Vec<char> {
    // The expected length is a + b + 1
    let expected_len = (a + b + 1) as usize;
    if s.len() != expected_len {
        return vec!['N', 'o'];
    }

    // The hyphen must be exactly at index `a`.
    let hyphen_idx = a as usize;
    if hyphen_idx >= s.len() || s[hyphen_idx] != '-' {
        return vec!['N', 'o'];
    }

    // All other positions must be digits.
    for (i, &ch) in s.iter().enumerate() {
        if i == hyphen_idx {
            continue;
        }
        if !ch.is_ascii_digit() {
            return vec!['N', 'o'];
        }
    }

    vec!['Y', 'e', 's']
}

